toolArgs.file_text:
.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    background: #2b2d31;
    color: #f2f3f5;
    padding: 1rem;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
}

::deep .sidebar-title {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #b5bac1;
    margin-bottom: 0.75rem;
}

::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

::deep .channel-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    cursor: pointer;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.25rem;
    transition: background-color 0.15s;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.95rem;
    flex: 1;
}

::deep .channel-description {
    width: 100%;
    font-size: 0.75rem;
    color: #b5bac1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #f23f43;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 8px;
    min-width: 1.2rem;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #f2f3f5;
    overflow: hidden;
}

::deep .message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #1e1f22;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
}

::deep .message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #b5bac1;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

::deep .loading-indicator {
    text-align: center;
    color: #b5bac1;
    padding: 0.5rem;
    font-size: 0.85rem;
}

/* Message Bubble */
::deep .message-bubble {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    position: relative;
    transition: background-color 0.1s;
}

::deep .message-bubble:hover {
    background: #2e3035;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
